INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Darf ein Arbeitgeber gemäß § 11 BBiG den Ausbildungsplan für Auszubildende festlegen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 11 BBiG verpflichtet und berechtigt den Arbeitgeber dazu"}, {"text": "Nein", "correct": false, "because": "Festlegung ist gesetzlich vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss der Arbeitgeber den Ausbildungsplan mit dem Auszubildenden abstimmen?', 2, '[{"text": "Ja", "correct": false, "because": "§ 11 BBiG verlangt keine Zustimmung des Auszubildenden"}, {"text": "Nein", "correct": true, "because": "Arbeitgeber hat Entscheidungsfreiheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Ausbildungsplan betriebliche Bedürfnisse berücksichtigen?', 2, '[{"text": "Ja", "correct": true, "because": "Flexibilität innerhalb des Ausbildungsrahmens erlaubt"}, {"text": "Nein", "correct": false, "because": "Betriebliche Anpassung ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss der Ausbildungsplan den Vorgaben des Ausbildungsrahmenplans entsprechen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 11 BBiG verlangt Übereinstimmung mit dem Rahmenplan"}, {"text": "Nein", "correct": false, "because": "Rahmenplan ist verbindlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Arbeitgeber den Ausbildungsplan während der Ausbildung ändern?', 2, '[{"text": "Ja", "correct": true, "because": "Anpassungen sind im Rahmen des § 11 BBiG möglich"}, {"text": "Nein", "correct": false, "because": "Änderungen sind erlaubt"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz gibt dem Arbeitgeber das Recht, den Ausbildungsplan festzulegen?', 2, '[{"text": "§ 11 BBiG", "correct": true, "because": "Regelt die Erstellung des Ausbildungsplans"}, {"text": "§ 14 Abs. 2 BBiG", "correct": false, "because": "Regelt andere Arbeitgeberrechte"}, {"text": "ArbSchG", "correct": false, "because": "Regelt Arbeitsschutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss ein Ausbildungsplan gemäß § 11 BBiG enthalten?', 3, '[{"text": "Zeitliche und sachliche Gliederung der Ausbildung", "correct": true, "because": "Gesetzliche Anforderung"}, {"text": "Nur die Arbeitszeiten", "correct": false, "because": "Zu eng gefasst"}, {"text": "Die Vergütungshöhe", "correct": false, "because": "Nicht Teil des Plans"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist primär für die Erstellung des Ausbildungsplans verantwortlich?', 2, '[{"text": "Der Arbeitgeber", "correct": true, "because": "§ 11 BBiG legt dies fest"}, {"text": "Die Berufsschule", "correct": false, "because": "Keine Zuständigkeit"}, {"text": "Der Auszubildende", "correct": false, "because": "Nur mitwirkend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einschränkung gilt für die Festlegung des Ausbildungsplans?', 3, '[{"text": "Einhaltung des Ausbildungsrahmenplans", "correct": true, "because": "Vorgabe der zuständigen Stelle"}, {"text": "Abstimmung mit der IHK", "correct": false, "because": "Keine direkte Pflicht"}, {"text": "Feste Arbeitszeiten", "correct": false, "because": "Anderes Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Vorteil hat der Arbeitgeber durch die Festlegung des Ausbildungsplans?', 3, '[{"text": "Strukturierte und betriebsgerechte Ausbildung", "correct": true, "because": "§ 11 BBiG ermöglicht Anpassung"}, {"text": "Weniger Verantwortung", "correct": false, "because": "Verantwortung bleibt"}, {"text": "Kürzere Ausbildungszeit", "correct": false, "because": "Zeit nicht beeinflusst"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welche Elemente muss ein Ausbildungsplan gemäß § 11 BBiG enthalten?', 4, '[{"text": "Zeitliche Gliederung", "correct": true, "because": "Planung der Phasen"}, {"text": "Sachliche Gliederung", "correct": true, "because": "Inhalte der Ausbildung"}, {"text": "Vergütungsdetails", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Ausbildungsziele", "correct": true, "because": "Orientierung am Rahmenplan"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte kann der Arbeitgeber bei der Festlegung des Ausbildungsplans berücksichtigen?', 3, '[{"text": "Betriebliche Abläufe", "correct": true, "because": "Anpassung möglich"}, {"text": "Ausbildungsrahmenplan", "correct": true, "because": "Verbindliche Vorgabe"}, {"text": "Wünsche des Auszubildenden", "correct": false, "because": "Keine Pflicht"}, {"text": "Fähigkeiten des Auszubildenden", "correct": true, "because": "Kann einfließen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten hat der Arbeitgeber bei der Festlegung des Ausbildungsplans?', 4, '[{"text": "Einhaltung des Rahmenplans", "correct": true, "because": "Gesetzlich vorgeschrieben"}, {"text": "Bereitstellung des Plans", "correct": true, "because": "§ 11 BBiG verlangt dies"}, {"text": "Abstimmung mit der Berufsschule", "correct": false, "because": "Nicht zwingend"}, {"text": "Berücksichtigung der Ausbildungsziele", "correct": true, "because": "Zielorientierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche gesetzlichen Grundlagen beeinflussen die Festlegung des Ausbildungsplans?', 3, '[{"text": "§ 11 BBiG", "correct": true, "because": "Regelt den Ausbildungsplan"}, {"text": "Ausbildungsrahmenplan", "correct": true, "because": "Verbindliche Vorgabe"}, {"text": "KSchG", "correct": false, "because": "Regelt Kündigungsschutz"}, {"text": "§ 14 Abs. 2 BBiG", "correct": false, "because": "Regelt andere Rechte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Festlegung des Ausbildungsplans durch den Arbeitgeber?', 3, '[{"text": "Strukturierte Ausbildung", "correct": true, "because": "Klarheit geschaffen"}, {"text": "Betriebliche Anpassung", "correct": true, "because": "Flexibilität gegeben"}, {"text": "Weniger Kosten", "correct": false, "because": "Nicht direkt beeinflusst"}, {"text": "Zielgerichtete Förderung", "correct": true, "because": "Fokus auf Ausbildungsziele"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Der Arbeitgeber darf den Ausbildungsplan festlegen. b) Er muss ihn mit dem Auszubildenden abstimmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) § 11 BBiG, b) falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Ausbildungsplan muss den Rahmenplan einhalten. b) Änderungen sind nicht erlaubt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (Anpassung möglich)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Betriebliche Bedürfnisse können berücksichtigt werden. b) Der Arbeitgeber hat keine Verantwortung dafür.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (§ 11 BBiG)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) § 11 BBiG regelt den Ausbildungsplan. b) Die Berufsschule erstellt ihn.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (Arbeitgeber zuständig)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Ausbildungsplan strukturiert die Ausbildung. b) Er muss die Ausbildungsziele fördern.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "a) Struktur, b) Zielorientierung"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');